1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Shared arithmetic — used by both the premium and the claim side.
43	// ---------------------------------------------------------------------------
44	
45	// Percentages MUST go through this helper. Multiplying first and dividing by
46	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
47	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
48	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
49	// that drift becomes a whole extra G.
50	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
51	
52	// Each item-level surcharge is "a percentage of this item's base premium, or
53	// nothing at all", so the condition is the only part that varies.
54	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
55	  applies ? percentOf(amount, percent) : 0;
56	
57	// ---------------------------------------------------------------------------
58	// Premium side — quoting a policy.
59	// ---------------------------------------------------------------------------
60	
61	const PROCESSING_FEE = 5;
62	
63	const FIRST_INSURANCE_PERCENT = 10;
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	const BLOCK_SIZE = 3;
75	const BLOCK_BASE_PREMIUM = 60;
76	
77	const countByType = (items: Item[]): Map<string, number> => {
78	  const counts = new Map<string, number>();
79	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
80	
81	  return counts;
82	};
83	
84	const basePremiumForType = (type: string, count: number): number =>
85	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  [...countByType(items)]
89	    .map(([type, count]) => basePremiumForType(type, count))
90	    .reduce((total, premium) => total + premium, 0);
91	
92	const CURSE_PERCENT = 50;
93	
94	const HIGH_ENCHANTMENT_PERCENT = 30;
95	const HIGH_ENCHANTMENT_THRESHOLD = 5;
96	
97	const itemSurcharge = (item: Item): number => {
98	  const base = BASE_PREMIUMS[item.type];
99	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
100	  const highEnchantmentSurcharge = percentOfWhen(
101	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
102	    base,
103	    HIGH_ENCHANTMENT_PERCENT,
104	  );
105	
106	  return curseSurcharge + highEnchantmentSurcharge;
107	};
108	
109	const itemSurcharges = (items: Item[]): number =>
110	  items.reduce((total, item) => total + itemSurcharge(item), 0);
111	
112	// Every modifier is a percentage of a base premium, and they are SUMMED rather
113	// than compounded: the spec's worked example reads
114	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
115	// so the first-insurance 10 % is taken on the policy base, not on the
116	// curse-inflated amount.
117	const LOYALTY_PERCENT = 20;
118	const LOYALTY_THRESHOLD_YEARS = 2;
119	
120	const FOLLOW_UP_PERCENT = 15;
121	
122	const quote = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): StepResult => {
123	  const policyBase = policyBasePremium(items);
124	
125	  // Surcharges add to the policy base, discounts subtract from it. Both are
126	  // percentages OF THE POLICY BASE (never of each other) — see the note above.
127	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
128	  const loyaltyDiscount = percentOfWhen(
129	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
130	    policyBase,
131	    LOYALTY_PERCENT,
132	  );
133	
134	  const followUpDiscount = percentOfWhen(isFollowUp, policyBase, FOLLOW_UP_PERCENT);
135	
136	  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge;
137	  const discounts = loyaltyDiscount + followUpDiscount;
138	  const total = policyBase + surcharges - discounts + PROCESSING_FEE;
139	
140	  return { premium: Math.ceil(total) };
141	};
142	
143	// ---------------------------------------------------------------------------
144	// Claim side — settling a payout against an open policy.
145	// ---------------------------------------------------------------------------
146	
147	const INSURANCE_VALUES: Record<string, number> = {
148	  sword: 1000,
149	  amulet: 600,
150	  staff: 800,
151	  potion: 400,
152	  rune: 250,
153	  moonstone: 250,
154	};
155	
156	const DEDUCTIBLE = 100;
157	const CAP_MULTIPLIER = 2;
158	
159	interface Policy {
160	  items: Item[];
161	  remainingCap: number;
162	}
163	
164	const openPolicy = (items: Item[]): Policy => ({
165	  items,
166	  remainingCap:
167	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0),
168	});
169	
170	// Settling a claim both answers the step and moves the policy on: successive
171	// claims draw down the same cap. Rather than writing through the caller's
172	// Policy, `claim` returns the policy it leaves behind, so the depletion is
173	// visible at the one place that owns the registry.
174	// The claim-side enchantment threshold (8) is deliberately NOT the premium-side
175	// one (5): a sword can be enchanted enough to cost more to insure without being
176	// enchanted enough to have its damage halved.
177	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
178	const HALVED_REIMBURSEMENT_PERCENT = 50;
179	
180	// How much of a damage amount the policy covers, BEFORE the deductible — the
181	// caller subtracts that. Special clauses are written as guards in precedence
182	// order: the first one that matches decides, so a clause that must win over
183	// another is simply written above it.
184	const coveredAmount = (damage: Damage, item: Item): number => {
185	  const isHighlyEnchanted = (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD;
186	  if (isHighlyEnchanted) return percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT);
187	
188	  return damage.amount;
189	};
190	
191	const claim = (
192	  { incident }: ClaimStep,
193	  policy: Policy,
194	): { result: StepResult; policy: Policy } => {
195	  const desiredPayout = incident.damages.reduce((total, damage) => {
196	    const item = policy.items.find(({ type }) => type === damage.itemType) as Item;
197	
198	    return total + (coveredAmount(damage, item) - DEDUCTIBLE);
199	  }, 0);
200	
201	  // The policy pays at most what is left of its cap; the excess is simply lost.
202	  const payout = Math.min(desiredPayout, policy.remainingCap);
203	  const remainingCap = policy.remainingCap - payout;
204	
205	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
206	};
207	
208	// The follow-up discount is about contract number, so only quote steps count —
209	// interleaved claim steps must not make the next quote look like a follow-up.
210	const isFollowUpQuote = (steps: Step[], index: number): boolean =>
211	  steps.slice(0, index).some((earlier) => earlier.op === "quote");
212	
213	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
214	  // Policies opened by quote steps, keyed by the step index a later claim cites.
215	  // Claims draw the cap down, so this registry is the one piece of carried state.
216	  const policies = new Map<number, Policy>();
217	
218	  const results = steps.map((step, index) => {
219	    if (step.op === "quote") {
220	      policies.set(index, openPolicy(step.items));
221	
222	      return quote(step, customer, isFollowUpQuote(steps, index));
223	    }
224	
225	    const settled = claim(step, policies.get(step.policy) as Policy);
226	    policies.set(step.policy, settled.policy);
227	
228	    return settled.result;
229	  });
230	
231	  return { results };
232	};
