// What a single damage entry is worth on its own: the covered amount that the
// item's clauses allow, less the deductible that every damaged item carries.
const payoutForDamage = (damage: Damage, items: Item[]): number => {
  const item = items.find(({ type }) => type === damage.itemType) as Item;

  return coveredAmount(damage, item) - DEDUCTIBLE;
};

const claim = (
  { incident }: ClaimStep,
  policy: Policy,
): { result: StepResult; policy: Policy } => {
  const desiredPayout = incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage, policy.items),
